member.example:
Handling the attachment upload start event:

<SfAIAssistView AttachmentUploadstart="OnStartUploading">
    <!-- Configuration -->
</SfAIAssistView>

@code {
    private Task OnStartUploading(UploadingEventArgs args)
    {
        Console.WriteLine($"Starting upload for file: {args.FileName}");
        return Task.CompletedTask;
    }
}

The following example demonstrates how to handle attachment uploads in an AI AssistView component:

<SfAIAssistView AttachmentUploadChange="OnChange">
    <!-- Configuration -->
</SfAIAssistView>

@code{
    private async Task OnChange(UploadChangeEventArgs args)
    {
        try
        {
            foreach (var file in args.Files)
            {
                var path = @"D:\" + file.FileInfo.Name;
                FileStream filestream = new FileStream(path, FileMode.Create, FileAccess.Write);
                await file.File.OpenReadStream(long.MaxValue).CopyToAsync(filestream);
                filestream.Close();
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine(ex.Message);
        }
    }
  }

Handling the successful upload event:

<SfAIAssistView AttachmentUploadSuccess="OnUploadSuccess">
    <!-- Configuration -->
</SfAIAssistView>

@code {
    private Task OnUploadSuccess(SuccessEventArgs args)
    {
        Console.WriteLine($"File uploaded successfully: {args.FileName}");
        return Task.CompletedTask;
    }
}

Handling an upload failure event:

<SfAIAssistView AttachmentUploadFailed="OnUploadFailed">
    <!-- Configuration -->
</SfAIAssistView>

@code {
    private Task OnUploadFailed(FailureEventArgs args)
    {
        Console.WriteLine($"Upload failed for file: {args.FileName}, Reason: {args.Reason}");
        return Task.CompletedTask;
    }
}

Handling the attachment removed event:

<SfAIAssistView AttachmentRemoved="OnAttachmentRemoved">
    <!-- Configuration -->
</SfAIAssistView>

@code {
    private Task OnAttachmentRemoved(RemovingEventArgs args)
    {
        Console.WriteLine($"Attachment removed: {args.FileName}");
        return Task.CompletedTask;
    }
}

Configuring attachment settings:

var attachmentSettings = new AssistViewAttachmentSettings
{
    Enable = true,
    SaveUrl = "https://myserver.com/api/Save",
    RemoveUrl = "https://myserver.com/api/Remove",
    AllowedFileTypes = ".jpg,.png,.pdf",
    MaxFileSize = 5000000 // 5 MB
};

Handling toolbar item clicks:

<MessageToolbar ItemClicked="OnToolbarItemClicked">
    <MessageToolbarItem IconCss="e-icons e-chat-reply"></MessageToolbarItem>
</MessageToolbar>

@code {
    private void OnToolbarItemClicked(MessageToolbarItemClickedEventArgs args)
    {
        // Handle the toolbar item click
        Console.WriteLine($"Clicked item: {args.Item.Text}");
    }
}

This example demonstrates how to set up a list of users for mentions:

var chat = new SfChat();
chat.MentionUsers = new List<UserModel>
{
    new UserModel { User = "John Doe" },
    new UserModel { User = "Jane Smith" }
};

This example shows how to customize the mention trigger character:

var chat = new SfChat();
chat.MentionChar = "#";
chat.MentionUsers = new List<UserModel>
{
    new UserModel { User = "John Doe" }
};

example.code:
// Create a new chat message with mentions
var message = new ChatMessage
{
    Id = "msg123",
    Text = "Hey @john, can you review the document with @sarah?",
    Time = DateTime.Now,
    MentionUsers = new UserModel[]
    {
        new UserModel { Id = "user1", User = "John Smith" },
        new UserModel { Id = "user2", user = "Sarah Johnson" }
    }
};

// Add the message to the chat
chatComponent.Messages.Add(message);

member.example:
Creating a pinned message:

var pinnedMessage = new ChatMessageModel
{
    Text = "Important announcement",
    IsPinned = true
};

Creating a reply message:

var replyMessage = new ChatMessageModel
{
    Text = "Thanks for the information!",
    RepliedTo = new MessageReplyModel
    {
        MessageID = "msg-123",
        Text = "Here's the project update",
        User = originalSender,
        Timestamp = DateTime.Now.AddMinutes(-5)
    }
};

Creating a forwarded message:

var forwardedMessage = new ChatMessageModel
{
    Text = "Check out this important update",
    IsForwarded = true
};

Creating a message reply model:

var replyModel = new MessageReplyModel
{
    User = originalAuthor,
    Text = "Original message content",
    MessageID = "msg-456",
    Timestamp = DateTime.Now.AddHours(-2),
    TimestampFormat = "MMM dd, yyyy hh:mm tt"
};
